// === ESTRUCTURA DEL PATRÓN STATE ===

// 1. Interfaz State (el contrato)
interface VendingState {
  insertMoney(amount: number): void;
  selectProduct(code: string): void;
  dispense(): void;
}

// 2. Estados Concretos
class WaitingForMoneyState implements VendingState {
  constructor(private machine: VendingMachine) {}

  insertMoney(amount: number) {
    this.machine.addBalance(amount);
    this.machine.setState(new HasMoneyState(this.machine));
    console.log(`Dinero insertado: $${amount}`);
  }

  selectProduct(code: string) {
    console.log('Primero debe insertar dinero');
  }

  dispense() {
    console.log('Primero debe insertar dinero');
  }
}

class HasMoneyState implements VendingState {
  constructor(private machine: VendingMachine) {}

  insertMoney(amount: number) {
    console.log('Ya tiene dinero insertado');
  }

  selectProduct(code: string) {
    this.machine.setProduct(code);
    this.machine.setState(new DispensingState(this.machine));
    console.log(`Producto seleccionado: ${code}`);
  }

  dispense() {
    console.log('Primero seleccione un producto');
  }
}

class DispensingState implements VendingState {
  constructor(private machine: VendingMachine) {}

  insertMoney(amount: number) {
    console.log('No puede insertar dinero mientras dispensa');
  }

  selectProduct(code: string) {
    console.log('Ya está dispensando un producto');
  }

  dispense() {
    console.log('Producto dispensado');
    this.machine.setState(new WaitingForMoneyState(this.machine));
  }
}

// 3. Contexto
class VendingMachine {
  private state: VendingState;
  private balance = 0;

  constructor() {
    this.state = new WaitingForMoneyState(this);
  }

  setState(state: VendingState) { this.state = state; }
  addBalance(amount: number) { this.balance += amount; }
  setProduct(code: string) { /* ... */ }

  insertMoney(amount: number) { this.state.insertMoney(amount); }
  selectProduct(code: string) { this.state.selectProduct(code); }
  dispense() { this.state.dispense(); }
}

// Uso:
const vm = new VendingMachine();
vm.dispense();          // 'Primero debe insertar dinero'
vm.insertMoney(100);    // 'Dinero insertado: $100'
vm.insertMoney(50);     // 'Ya tiene dinero insertado'
vm.selectProduct('A1'); // 'Producto seleccionado: A1'
vm.dispense();          // 'Producto dispensado'

