interface OrderState {
  ship(order: Order): void;
  deliver(order: Order): void;
  cancel(order: Order): void;
}

// 2. Estados concretos
class PendingState implements OrderState {
  ship(order: Order) {
    console.log('No puede enviar: pedido pendiente');
  }
  deliver(order: Order) {
    console.log('No puede entregar: pedido pendiente');
  }
  cancel(order: Order) {
    order.setState(new CancelledState());
    console.log('Pedido cancelado');
  }
}

class PaidState implements OrderState {
  ship(order: Order) {
    order.setState(new ShippedState());
    console.log('Pedido enviado');
  }
  deliver(order: Order) {
    console.log('No puede entregar: primero debe enviar');
  }
  cancel(order: Order) {
    order.setState(new CancelledState());
    console.log('Pedido cancelado con reembolso');
  }
}

// 3. El Contexto delega al estado actual
class Order {
  private state: OrderState = new PendingState();

  setState(state: OrderState) { this.state = state; }
  ship() { this.state.ship(this); }
  deliver() { this.state.deliver(this); }
  cancel() { this.state.cancel(this); }
}

